window.docContents[68].resolve({"/Preface/#Type-Systems--Preface--Practicalities--Citation-Format":{"contents":"If you want to refer to this volume in your own writing, please\ndo so as follows:\n\n@book            {SFL:3,\nauthor       =   {Mike Hicks and Benjamin C. Pierce and the SF-in-Lean team},\ntitle        =   \"Type Systems\",\nseries       =   \"Software Foundations in Lean\",\nvolume       =   \"3\",\nyear         =   \"2026\",\npublisher    =   \"Electronic textbook\",\nnote         =   {Version 0.1.0, \\URL<https://github.com/plclub/sf-in-lean>}\n}\n\n","context":"Type Systems\u0009Preface\u0009Practicalities","header":"1.3.2. Citation Format","id":"/Preface/#Type-Systems--Preface--Practicalities--Citation-Format"},"/References/#Type-Systems--References___-Typing-Mutable-References--Operational-Semantics--Reduction":{"contents":"First, we augment existing reduction rules with stores:            v₂.IsValue\n------------------------------------ (appAbs)\n(λx:τ₂. t₁) v₂ / ρ ⟶ [x:=v₂] t₁ / ρ\n\n            t₁ / ρ ⟶ t₁' / ρ'\n---------------------------------    (app₁)\n         t₁ t₂ / ρ ⟶ t₁' t₂ / ρ'\n\n           v₁.IsValue\n            t₂ / ρ ⟶ t₂' / ρ'\n---------------------------------    (app₂)\n         v₁ t₂ / ρ ⟶ v₁ t₂' / ρ'\nNow we can give the rules for the new constructs:------------------------------------    (refValue)\n     ref v / ρ ⟶ loc ρ.length / ρ,v\n\n        t₁ / ρ ⟶ t₁' / ρ'\n------------------------------          (ref)\n    ref t₁ / ρ ⟶ ref t₁' / ρ'\n\n      l < ρ.length\n--------------------------              (derefLoc)\n  !(loc l) / ρ ⟶ ρ[l] / ρ\n\n        t₁ / ρ ⟶ t₁' / ρ'\n---------------------------             (deref)\n       !t₁ / ρ ⟶ !t₁' / ρ'\n\n             l < ρ.length\n--------------------------------------- (assign)\nloc l := v / ρ ⟶ unit / List.set ρ l v\n\n        t₁ / ρ ⟶ t₁' / ρ'\n--------------------------------        (assign₁)\n  t₁ := t₂ / ρ ⟶ t₁' := t₂ / ρ'\n\n        t₂ / ρ ⟶ t₂' / ρ'\n--------------------------------        (assign₂)\n  v₁ := t₂ / ρ ⟶ v₁ := t₂' / ρ'\n\n\n\n\nsection\nset_option hygiene false in\nlocal notation:40\n  t:71 \" / \" ρ:41 \" ⟶ \" t':71 \" / \" ρ':41 =>\n  Step (t, ρ) (t', ρ')\n\ninductive Step : Tm × Store → Tm × Store → Prop where\n  -- pure STLC\n  | appAbs {x : String} {τ₂ : Ty} {t₁ v₂ : Tm} {ρ : Store}\n      (h : v₂.IsValue) :\n      <{(λ x : τ₂ . t₁) v₂}> / ρ ⟶\n      <{ [x := v₂] t₁ }> / ρ\n  | app₁ {t₁ t₁' t₂ : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{t₁ t₂}> / ρ ⟶ <{t₁' t₂}> / ρ'\n  | app₂ {v₁ t₂ t₂' : Tm} {ρ ρ' : Store}\n      (h₁ : v₁.IsValue)\n      (h₂ : t₂ / ρ ⟶ t₂' / ρ') :\n      <{v₁ t₂}> / ρ ⟶ <{v₁ t₂'}> / ρ'\n  -- numbers\n  | succNat {n : Nat} {ρ : Store} :\n      <{ succ ~(Tm.const n) }> / ρ ⟶ Tm.const (n + 1) / ρ\n  | succ {t₁ t₁' : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ succ t₁ }> / ρ ⟶ <{ succ t₁' }> / ρ'\n  | predConst {n : Nat} {ρ : Store} :\n      <{ pred ~(Tm.const n) }> / ρ ⟶ Tm.const (n - 1) / ρ\n  | pred {t₁ t₁' : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ pred t₁ }> / ρ ⟶ <{ pred t₁' }> / ρ'\n  | multConst {n₁ n₂ : Nat} {ρ : Store} :\n      <{ ~(Tm.const n₁) * ~(Tm.const n₂) }> / ρ ⟶\n      Tm.const (n₁ * n₂) / ρ\n  | mult₁ {t₁ t₁' t₂ : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ t₁ * t₂ }> / ρ ⟶ <{ t₁' * t₂ }> / ρ'\n  | mult₂ {v₁ t₂ t₂' : Tm} {ρ ρ' : Store}\n      (h₁ : v₁.IsValue)\n      (h₂ : t₂ / ρ ⟶ t₂' / ρ') :\n      <{ v₁ * t₂ }> / ρ ⟶ <{ v₁ * t₂' }> / ρ'\n  | if0Step {t₁ t₁' t₂ t₃ : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ if0 t₁ then t₂ else t₃ }> / ρ ⟶\n      <{ if0 t₁' then t₂ else t₃ }> / ρ'\n  | if0Zero {t₂ t₃ : Tm} {ρ : Store} :\n      <{ if0 0 then t₂ else t₃ }> / ρ ⟶ t₂ / ρ\n  | if0Nonzero {n : Nat} {t₂ t₃ : Tm} {ρ : Store} :\n      <{ if0 ~(Tm.const (n + 1)) then t₂ else t₃ }> / ρ ⟶\n      t₃ / ρ\n  -- references\n  | refValue {v : Tm} {ρ : Store}\n      (h : v.IsValue) :\n      <{ ref v }> / ρ ⟶ Tm.loc ρ.length / ρ.concat v\n  | ref_ {t₁ t₁' : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ ref t₁ }> / ρ ⟶ <{ ref t₁' }> / ρ'\n  | derefLoc {l : Nat} {ρ : Store}\n      (h : l < ρ.length) :\n      <{ !~(Tm.loc l) }> / ρ ⟶ ρ[l] / ρ\n  | deref {t₁ t₁' : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ !t₁ }> / ρ ⟶ <{ !t₁' }> / ρ'\n  | assign {v : Tm} {l : Nat} {ρ : Store}\n      (h₁ : v.IsValue)\n      (h₂ : l < ρ.length) :\n      <{ ~(Tm.loc l) := v }> / ρ ⟶ <{ unit }> / ρ.set l v\n  | assign₁ {t₁ t₁' t₂ : Tm} {ρ ρ' : Store}\n      (h : t₁ / ρ ⟶ t₁' / ρ') :\n      <{ t₁ := t₂ }> / ρ ⟶ <{ t₁' := t₂ }> / ρ'\n  | assign₂ {v₁ t₂ t₂' : Tm} {ρ ρ' : Store}\n      (h₁ : v₁.IsValue)\n      (h₂ : t₂ / ρ ⟶ t₂' / ρ') :\n      <{ v₁ := t₂ }> / ρ ⟶ <{ v₁ := t₂' }> / ρ'\nend\n\nscoped notation:40\n  t:71 \" / \" ρ:41 \" ⟶ \" t':71 \" / \" ρ':41 =>\n  Step (t, ρ) (t', ρ')\nscoped notation:40\n  t:71 \" / \" ρ:41 \" ⟶* \" t':71 \" / \" ρ':41 =>\n  Multi Step (t, ρ) (t', ρ')\n\nattribute [StlcRefEval] Step.appAbs Step.app₁ Step.app₂\n    Step.succ Step.succNat Step.pred Step.predConst\n    Step.multConst Step.mult₁ Step.mult₂\n    Step.if0Step Step.if0Zero Step.if0Nonzero\n    Step.refValue Step.ref_ Step.derefLoc Step.deref Step.assign\n    Step.assign₁ Step.assign₂\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Operational Semantics","header":"9.3.3. Reduction","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Operational-Semantics--Reduction"},"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions":{"contents":"\n\n* A simple toy language where expressions may fail with dynamic type\n    errors* numbers (and arithmetic)* booleans (and conditionals)* This means we can write stuck terms like 5 + true and\n    if 42 then 0 else 1.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Types: Type Systems","header":"4.1. Typed Arithmetic Expressions","id":"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions"}});